import pickle,warnings,numpy as np,pandas as pd,itertools
from pymatgen.core import Element
from ase.data import covalent_radii
warnings.filterwarnings('ignore')
df,ss,meta=pickle.load(open('/tmp/structures.pkl','rb'))
props=['Z','X','atomic_mass','atomic_radius','atomic_radius_calculated','mendeleev_no','row','group','electron_affinity','average_ionic_radius','average_cationic_radius','average_anionic_radius']
elts=sorted(set(str(x.specie) for s in ss for x in s))
def ep(e):
 el=Element(e); out=[]
 for p in props:
  try: val=float(getattr(el,p))
  except: val=0.
  out.append(val if np.isfinite(val) else 0)
 out.extend([covalent_radii[el.Z],float(el.is_alkali),float(el.is_alkaline),float(el.is_transition_metal),float(el.is_post_transition_metal),float(el.is_metalloid),float(el.is_halogen),float(el.is_chalcogen),float(el.is_lanthanoid)])
 return np.array(out)
props+=['rcov','alkali','alkaline','transition','posttransition','metalloid','halogen','chalcogen','lanthanide']
epmap={e:ep(e) for e in elts}
# 10 independent tensor components
inds=list(itertools.combinations_with_replacement(range(3),3))
def tensor(v): return np.array([v[:,i]*v[:,j]*v[:,k] for i,j,k in inds]).T

def addstats(f,p,x,w=None):
 x=np.array(x)
 if len(x)==0: return
 if w is None: w=np.ones(len(x))/len(x)
 else: w=np.array(w)/np.sum(w)
 mean=np.sum(x*w); f[p+'_mean']=mean; f[p+'_std']=np.sqrt(np.sum((x-mean)**2*w));f[p+'_min']=x.min();f[p+'_max']=x.max()

def td(f,p,ts,locals=None):
 f[p+'_max']=np.max(np.abs(ts));f[p+'_norm']=np.linalg.norm(ts)
 f[p+'_diag']=np.max(np.abs(ts[:3])) if False else max(abs(ts[0]),abs(ts[6]),abs(ts[9]))
 # xxx xxy xxz xyy xyz xzz yyy yyz yzz zzz
 f[p+'_off']=np.max(np.abs(ts[[1,2,3,4,5,7,8]])); f[p+'_xyz']=abs(ts[4])
 for k,t in enumerate(ts):f[p+'_'+str(k)]=abs(t)
 if locals is not None:
  f[p+'_coherence']=np.linalg.norm(ts)/(np.sum(np.linalg.norm(locals,axis=1))+1e-12)

rows=[]
for ind,s in enumerate(ss):
 f={}; frac=s.composition.fractional_composition.get_el_amt_dict(); species=np.array([str(site.specie) for site in s]); ps=np.array([epmap[e] for e in species]); n=len(s)
 for e in elts: f['frac_'+e]=frac.get(e,0)
 for j,p in enumerate(props): addstats(f,'el_'+p,ps[:,j])
 f['nelements']=len(frac); f['entropy']=-np.sum([v*np.log(v) for v in frac.values()]);f['n']=n;f['vpa']=s.volume/n;f['density']=float(s.density);f['sg']=meta.iloc[ind].sg
 f['packing']=sum(4*np.pi/3*covalent_radii[site.specie.Z]**3 for site in s)/s.volume
 for j,a in enumerate(sorted(s.lattice.abc)):f['lat_'+str(j)]=a
 for j,a in enumerate(sorted(s.lattice.angles)):f['angle_'+str(j)]=a
 for pg in sorted(set(meta.pg)): f['pg_'+pg]=int(meta.iloc[ind].pg==pg)
 # cation-anion chemical props
 anions=np.array([Element(e).X>=2.05 for e in species]);
 for mask,pr in [(anions,'anion'),(~anions,'cation')]:
  f[pr+'_frac']=mask.mean()
  for j,p in enumerate(props):addstats(f,pr+'_'+p,ps[mask,j])
 # neighbor vectors all firstshells (nearest shell adaptive) and nearest heteropolar (fixed four)
 nbs=s.get_all_neighbors(6.5)
 tensors={}; locprops={}; allbonds=[]; bdprops=[]
 for i,site in enumerate(s):
  e=str(site.specie); cen=Element(e); neigh=sorted(nbs[i],key=lambda x:x.nn_distance)
  if not neigh:continue
  rmin=neigh[0].nn_distance
  shell=[x for x in neigh if x.nn_distance<rmin*1.25]
  hetero=[x for x in neigh if (Element(str(x.specie)).X-cen.X)*(-1 if anions[i] else 1)>.15]
  hs=hetero[:4]
  for mode,sh in [('shell',shell),('het4',hs)]:
   if not sh:continue
   vec=np.array([x.coords-site.coords for x in sh]);ds=np.linalg.norm(vec,axis=1);u=vec/ds[:,None]
   # orient consistently from low electroneg toward high
   signs=np.array([np.sign(Element(str(x.specie)).X-cen.X) for x in sh]);ut=u*signs[:,None]
   if mode=='het4' and anions[i]:continue
   bp=ps[i]; local_t=tensor(ut)
   cs=(u@u.T)[np.triu_indices(len(sh),1)]
   for key, val in [('coord',len(sh)),('dist',ds.mean()),('distmin',ds.min()),('distmax',ds.max()),('diststd',ds.std()),('cosmean',cs.mean() if len(cs) else 0),('cosstd',cs.std() if len(cs) else 0),('tetdistort',np.mean((cs+1/3)**2) if len(cs) else 0),('dipole',np.linalg.norm(u.sum(axis=0))),('localT',np.linalg.norm(local_t.sum(axis=0)))]:
    for group in ['all',e,'anions' if anions[i] else 'cations']:
     locprops.setdefault(mode+'_'+group+'_'+key,[]).append(val)
   for power in [0,-3,3]:
    lt=np.sum(local_t*(ds[:,None]**power),axis=0)/s.volume
    groups={'all':1,e:1,'anions' if anions[i] else 'cations':1}
    if mode=='het4':
     for p in ['Z','X','rcov','atomic_radius','group','electron_affinity']:
      groups['wt_'+p]=bp[props.index(p)]
    for group,w in groups.items(): tensors.setdefault(mode+'_'+group+'_p'+str(power),[]).append(lt*w)
   if mode=='shell':
    for nb,d in zip(sh,ds):
     en=Element(str(nb.specie)); gap=abs(cen.X-en.X)
     allbonds.append([d,gap,d/(covalent_radii[cen.Z]+covalent_radii[en.Z]),float(en.Z==cen.Z)])
 for name,v in locprops.items():addstats(f,name,v)
 for name,ls in tensors.items():
  ls=np.array(ls);td(f,name,ls.sum(axis=0),ls)
 for j,k in enumerate(['dist','Xgap','rel_dist','same_element']):addstats(f,'bonds_'+k,np.array(allbonds)[:,j])
 rows.append(f)
 if ind%50==0:print(ind,flush=True)
X=pd.DataFrame(rows).fillna(0)
pickle.dump(X,open('/tmp/features.pkl','wb'))
print(X.shape)

